    def sync_news(self, send_ids=None, do_auto_convert=True):
        if not self.device_connected:
            return
        del_on_upload = config['delete_news_from_library_on_upload']
        settings = self.device_manager.device.settings()
        ids = list(self.news_to_be_synced) if send_ids is None else send_ids
        ids = [id for id in ids if self.library_view.model().db.has_id(id)]
        with BusyCursor():
            files, _auto_ids = self.library_view.model().get_preferred_formats_from_ids(
                                ids, settings.format_map,
                                exclude_auto=do_auto_convert)
        auto = self._collect_auto_ids(_auto_ids, settings, do_auto_convert)
        if auto:
            self._handle_auto_convert(auto, settings)
        files = [f for f in files if f is not None]
        if not files:
            self.news_to_be_synced = set([])
            return
        metadata = self.library_view.model().metadata_for(ids)
        names = self._build_names(metadata, files)
        self.news_to_be_synced = set([])
        if config['upload_news_to_device'] and files:
            remove = ids if del_on_upload else []
            space = {self.location_manager.free[0]: None,
                     self.location_manager.free[1]: 'carda',
                     self.location_manager.free[2]: 'cardb'}
            on_card = space.get(sorted(space.keys(), reverse=True)[0], None)
            total_size = self._calculate_total_size(files)
            loc = tweaks['send_news_to_device_location']
            loc_index = {"carda": 1, "cardb": 2}.get(loc, 0)
            if self.location_manager.free[loc_index] > total_size + (1024**2):
                on_card = loc if loc in ('carda', 'cardb') else None
            self.upload_books(files, names, metadata,
                    on_card=on_card,
                    memory=[files, remove])
            self.status_bar.show_message(_('Sending news to device.'), 5000)

    def _calculate_total_size(self, files):
        try:
            return sum([os.stat(f).st_size for f in files])
        except:
            try:
                import traceback
                traceback.print_exc()
            except:
                pass
            return self.location_manager.free[0]

    def sync_to_device(self, on_card, delete_from_library,
            specific_format=None, send_ids=None, do_auto_convert=True):
        ids = self._gather_ids(send_ids)
        if not self._can_sync(ids):
            return

        settings = self.device_manager.device.settings()
        with BusyCursor():
            _files, _auto_ids = self.library_view.model().get_preferred_formats_from_ids(
                                    ids, settings.format_map,
                                    specific_format=specific_format,
                                    exclude_auto=do_auto_convert)
        ids, _files = self._filter_auto_ids(ids, _files, _auto_ids, do_auto_convert)
        metadata = self.library_view.model().metadata_for(ids)
        self._prepare_metadata(metadata)
        good, names, remove_ids = self._process_files(_files, metadata, ids)
        self.upload_books(good, names, metadata, on_card, memory=(_files, remove_ids))
        self.status_bar.show_message(_('Sending books to device.'), 5000)
        self._handle_auto_conversion(_auto_ids, specific_format, settings, ids)

    def _gather_ids(self, send_ids):
        if send_ids is not None:
            return send_ids
        return [self.library_view.model().id(r)
               for r in self.library_view.selectionModel().selectedRows()]

    def _can_sync(self, ids):
        if not self.device_manager or not ids or not self.device_manager.is_device_connected:
            return False
        return True

    def _filter_auto_ids(self, ids, _files, _auto_ids, do_auto_convert):
        if do_auto_convert:
            ok_ids = set(ids).difference(_auto_ids)
            ids = [i for i in ids if i in ok_ids]
        else:
            _auto_ids = []
        return ids, _files

    def _prepare_metadata(self, metadata):
        for mi in metadata:
            self.update_thumbnail(mi)

    def _process_files(self, _files, metadata, ids):
        good, names, remove_ids = [], [], []
        for f, mi, id_ in zip(_files, metadata, ids):
            if f is None:
                continue
            remove_ids.append(id_)
            good.append(f)
            prefix = self._make_prefix(mi)
            names.append('%s_%d%s' % (prefix, id_, os.path.splitext(f)[1]))
        return good, names, remove_ids

    def _make_prefix(self, mi):
        t = mi.title or _('Unknown')
        a = mi.format_authors() or _('Unknown')
        prefix = ascii_filename(t + ' - ' + a)
        if not isinstance(prefix, unicode):
            prefix = prefix.decode(preferred_encoding, 'replace')
        return ascii_filename(prefix)

    def _handle_auto_conversion(self, _auto_ids, specific_format, settings, ids):
        if not _auto_ids:
            return
        auto = self._determine_auto_ids(_auto_ids, specific_format, settings)
        if not auto:
            return
        fmt = self._choose_auto_format(specific_format, settings)
        if fmt is None:
            return
        autos = [self.library_view.model().db.title(id_, index_is_id=True) for id_ in auto]
        if self.auto_convert_question(
            _('Auto convert the following books before uploading to '
                'the device?'), autos):
            self.iactions['Convert Books'].auto_convert(auto, on_card, fmt)

    def _determine_auto_ids(self, _auto_ids, specific_format, settings):
        auto = []
        for id in _auto_ids:
            if specific_format is None:
                formats = self.library_view.model().db.formats(id, index_is_id=True)
                formats = formats.split(',') if formats else []
                formats = [f.lower().strip() for f in formats]
                if set(formats).intersection(available_input_formats()) and \
                   set(settings.format_map).intersection(available_output_formats()):
                    auto.append(id)
            else:
                if specific_format in set(settings.format_map).intersection(set(available_output_formats())):
                    auto.append(id)
        return auto

    def _choose_auto_format(self, specific_format, settings):
        if specific_format and specific_format in set(settings.format_map).intersection(set(available_output_formats())):
            return specific_format
        for fmt in settings.format_map:
            if fmt in set(settings.format_map).intersection(set(available_output_formats())):
                return fmt
        return None

    def upload_dirtied_booklists(self):
        '''
        Upload metadata to device.
        '''
        plugboards = self.library_view.model().db.prefs.get('plugboards', {})
        self.device_manager.sync_booklists(Dispatcher(lambda x: x),
                                           self.booklists(), plugboards)

    def upload_booklists(self, add_as_step_to_job=None):
        '''
        Upload metadata to device.
        '''
        plugboards = self.library_view.model().db.prefs.get('plugboards', {})
        self.device_manager.sync_booklists(FunctionDispatcher(self.metadata_synced),
                                           self.booklists(), plugboards,
                                           add_as_step_to_job=add_as_step_to_job)

    def metadata_synced(self, job):
        '''
        Called once metadata has been uploaded.
        '''
        if job.failed:
            self.device_job_exception(job)
            return
        cp, fs = job.result
        self.location_manager.update_devices(cp, fs,
                self.device_manager.device.icon)
        cv, row = self.current_view(), -1
        if cv is not self.library_view:
            row = cv.currentIndex().row()
        self.memory_view.reset()
        self.card_a_view.reset()
        self.card_b_view.reset()
        if row > -1:
            cv.set_current_row(row)

    def _upload_collections(self, job):
        if job.failed:
            self.device_job_exception(job)

    def upload_collections(self, booklist, view=None, oncard=None):
        return self.device_manager.upload_collections(self._upload_collections,
                                                       booklist, oncard)

    def upload_books(self, files, names, metadata, on_card=None, memory=None):
        '''
        Upload books to device.
        :param files: List of either paths to files or file like objects
        '''
        titles = [i.title for i in metadata]
        plugboards = self.library_view.model().db.prefs.get('plugboards', {})
        job = self.device_manager.upload_books(
                FunctionDispatcher(self.books_uploaded),
                files, names, on_card=on_card,
                metadata=metadata, titles=titles, plugboards=plugboards
              )
        self.upload_memory[job] = (metadata, on_card, memory, files)

    def books_uploaded(self, job):
        '''
        Called once books have been uploaded.
        '''
        metadata, on_card, memory, files = self.upload_memory.pop(job)

        if job.exception is not None:
            self._handle_upload_exception(job, metadata)
            return

        try:
            self.device_manager.add_books_to_metadata(job.result,
                    metadata, self.booklists())
        except:
            traceback.print_exc()
            raise

        if memory and memory[1]:
            self.library_view.model().delete_books_by_id(memory[1])

        if not self.set_books_in_library(self.booklists(), reset=True,
                                     add_as_step_to_job=job, do_device_sync=False):
            self.upload_booklists(job)
        self.refresh_ondevice()

        view = self._select_view(on_card)
        view.model().resort(reset=False)
        view.model().research()
        self._cleanup_temp_files(files)

    def _handle_upload_exception(self, job, metadata):
        if isinstance(job.exception, FreeSpaceError):
            where = 'in main memory.' if 'memory' in str(job.exception) else 'on the storage card.'
            titles = '\n'.join(['<li>'+mi.title+'</li>' for mi in metadata])
            d = error_dialog(self, _('No space on device'),
                             _('<p>Cannot upload books to device there '
                             'is no more free space available ')+where+
                             '</p>\n<ul>%s</ul>'%(titles,))
            d.exec_()
        elif isinstance(job.exception, WrongDestinationError):
            error_dialog(self, _('Incorrect destination'),
                    unicode(job.exception), show=True)
        else:
            self.device_job_exception(job)

    def _select_view(self, on_card):
        if on_card == 'carda':
            return self.card_a_view
        if on_card == 'cardb':
            return self.card_b_view
        return self.memory_view

    def _cleanup_temp_files(self, files):
        for f in files:
            try:
                rem = not getattr(self.device_manager.device,
                        'KEEP_TEMP_FILES_AFTER_UPLOAD', False)
                if rem and 'caltmpfmt.' in f:
                    os.remove(f)
            except:
                pass

    def update_metadata_on_device(self):
        self.set_books_in_library(self.booklists(), reset=True, force_send=True)
        self.refresh_ondevice()

    def set_current_library_information(self, library_name, library_uuid, field_metadata):
        self.device_manager.set_current_library_uuid(library_uuid)
        if self.device_manager.is_device_connected:
            self.device_manager.set_library_information(None, library_name,
                                            library_uuid, field_metadata)

    def book_on_device(self, id, reset=False):
        '''
        Return an indication of whether the given book represented by its db id
        is on the currently connected device. It returns a 5 element list. The
        first three elements represent memory locations main, carda, and cardb,
        and are true if the book is identifiably in that memory. The fourth
        is a count of how many instances of the book were found across all
        the memory locations. The fifth is a set of paths to the
        matching books on the device.
        '''
        loc = [None, None, None, 0, set([])]

        if reset:
            self.book_db_id_cache = None
            self.book_db_id_counts = None
            self.book_db_uuid_path_map = None
            return

        if not self.device_manager.is_device_connected or \
                        not hasattr(self, 'db_book_uuid_cache'):
            return loc

        if self.book_db_id_cache is None:
            self._initialize_book_caches()

        for i, l in enumerate(self.booklists()):
            if id in self.book_db_id_cache[i]:
                loc[i] = True
                loc[3] = self.book_db_id_counts.get(id, 0)
                loc[4] |= self.book_db_uuid_path_map[id]
        return loc

    def _initialize_book_caches(self):
        self.book_db_id_cache = []
        self.book_db_id_counts = {}
        self.book_db_uuid_path_map = {}
        db = self.library_view.model().db
        for i, l in enumerate(self.booklists()):
            self.book_db_id_cache.append(set())
            for book in l:
                db_id = getattr(book, 'application_id', None)
                if db_id is not None:
                    self.book_db_id_cache[i].add(db_id)
                    self.book_db_id_counts[db_id] = self.book_db_id_counts.get(db_id, 0) + 1
                    if getattr(book, 'lpath', False):
                        self.book_db_uuid_path_map.setdefault(db_id, set()).add(book.lpath)

    def update_thumbnail(self, book):
        if book.cover and os.access(book.cover, os.R_OK):
            with lopen(book.cover, 'rb') as f:
                book.thumbnail = self.cover_to_thumbnail(f.read())
        else:
            cprefs = self.default_thumbnail_prefs
            book.thumbnail = (cprefs['cover_width'], cprefs['cover_height'], generate_cover(book, prefs=cprefs))

    def set_books_in_library(self, booklists, reset=False, add_as_step_to_job=None,
                             force_send=False, do_device_sync=True):
        '''
        Set the ondevice indications in the device database.
        This method should be called before book_on_device is called, because
        it sets the application_id for matched books. Book_on_device uses that
        to both speed up matching and to count matches.
        '''
        if not self.device_manager.is_device_connected:
            return False

        try:
            db = self.library_view.model().db
        except:
            return False

        if reset or not hasattr(self, 'db_book_title_cache'):
            self._build_library_caches(db)

        update_metadata = self._should_update_metadata(force_send)
        get_covers = self._needs_covers(update_metadata)
        desired_thumbnail_height = self._desired_thumbnail_height(update_metadata)

        total_book_count = sum(1 for bl in booklists for b in bl if b)
        if DEBUG:
            prints('DeviceJob: set_books_in_library: books to process=', total_book_count)

        start_time = time.time()
        with BusyCursor():
            self._process_device_books(booklists, db, update_metadata,
                                       get_covers, desired_thumbnail_height,
                                       do_device_sync, add_as_step_to_job)
        if DEBUG:
            prints('DeviceJob: set_books_in_library finished: time=',
                   time.time() - start_time)
        return update_metadata

    def _should_update_metadata(self, force_send):
        return (device_prefs['manage_device_metadata'] == 'on_connect' or force_send)

    def _needs_covers(self, update_metadata):
        return update_metadata and self.device_manager.is_device_connected and \
               self.device_manager.device.WANTS_UPDATED_THUMBNAILS

    def _desired_thumbnail_height(self, update_metadata):
        if self._needs_covers(update_metadata):
            return self.device_manager.device.THUMBNAIL_HEIGHT
        return 0

    def _build_library_caches(self, db):
        string_pat = re.compile('(?u)\W|[_]')

        def clean_string(x):
            x = x.lower() if x else ''
            return string_pat.sub('', x)

        db_book_title_cache = {}
        db_book_uuid_cache = {}
        for id_ in db.data.iterallids():
            title = clean_string(db.title(id_, index_is_id=True))
            if title not in db_book_title_cache:
                db_book_title_cache[title] = {'authors':{}, 'author_sort':{}, 'db_ids':{}}
            authors = clean_string(db.authors(id_, index_is_id=True))
            if authors:
                db_book_title_cache[title]['authors'][authors] = id_
            if db.author_sort(id_, index_is_id=True):
                aus = clean_string(db.author_sort(id_, index_is_id=True))
                db_book_title_cache[title]['author_sort'][aus] = id_
            db_book_title_cache[title]['db_ids'][id_] = id_
            db_book_uuid_cache[db.uuid(id_, index_is_id=True)] = id_
        self.db_book_title_cache = db_book_title_cache
        self.db_book_uuid_cache = db_book_uuid_cache

    def _process_device_books(self, booklists, db, update_metadata,
                              get_covers, desired_thumbnail_height,
                              do_device_sync, add_as_step_to_job):
        book_ids_to_refresh = set()
        book_formats_to_send = []
        books_with_future_dates = []
        first_call = [True]

        for booklist in booklists:
            for book in booklist:
                if not book:
                    continue
                self._process_single_book(book, db, update_metadata,
                                          get_covers, desired_thumbnail_height,
                                          first_call, book_ids_to_refresh,
                                          book_formats_to_send,
                                          books_with_future_dates)

        if update_metadata and do_device_sync:
            self._sync_metadata(booklists, add_as_step_to_job)

        if book_ids_to_refresh:
            self._refresh_gui(book_ids_to_refresh)

        if book_formats_to_send:
            self._upload_missing_formats(book_formats_to_send, db)

        if books_with_future_dates:
            self._show_future_date_warning(books_with_future_dates)

    def _process_single_book(self, book, db, update_metadata,
                             get_covers, desired_thumbnail_height,
                             first_call, book_ids_to_refresh,
                             book_formats_to_send, books_with_future_dates):
        book.in_library = None
        uuid = getattr(book, 'uuid', None)
        if uuid and uuid in self.db_book_uuid_cache:
            id_ = self.db_book_uuid_cache[uuid]
            if self._needs_update(id_, book, db, update_metadata,
                                  get_covers, desired_thumbnail_height,
                                  first_call):
                self._update_book_metadata(id_, book, db, get_covers, desired_thumbnail_height)
            book.in_library = 'UUID'
            book.application_id = id_
            return

        title_key = self._clean_string(book.title)
        cache_entry = self.db_book_title_cache.get(title_key)
        if cache_entry:
            self._match_by_title(cache_entry, book, db, update_metadata,
                                 get_covers, desired_thumbnail_height,
                                 first_call, book_ids_to_refresh,
                                 book_formats_to_send, books_with_future_dates)
        else:
            book.application_id = None

    def _clean_string(self, x):
        string_pat = re.compile('(?u)\W|[_]')
        x = x.lower() if x else ''
        return string_pat.sub('', x)

    def _needs_update(self, id_, book, db, update_metadata,
                      get_covers, desired_thumbnail_height, first_call):
        if not update_metadata:
            return False
        if do_device_sync and self.device_manager.device is not None:
            set_of_ids, (fmt_name, date_bad) = \
                self.device_manager.device.synchronize_with_db(db, id_, book,
                                                               first_call[0])
            first_call[0] = False
            if date_bad:
                books_with_future_dates.append(book.title)
            elif fmt_name:
                book_formats_to_send.append((id_, fmt_name))
            if set_of_ids:
                book_ids_to_refresh.update(set_of_ids)
                return True
        return (db.metadata_last_modified(id_, index_is_id=True) !=
                getattr(book, 'last_modified', None) or
                (isinstance(getattr(book, 'thumbnail', None), (list, tuple)) and
                 max(book.thumbnail[0], book.thumbnail[1]) != desired_thumbnail_height))

    def _update_book_metadata(self, id_, book, db, get_covers, desired_thumbnail_height):
        mi = db.get_metadata(id_, index_is_id=True, get_cover=get_covers)
        book.smart_update(mi, replace_metadata=True)
        if get_covers and desired_thumbnail_height != 0:
            self.update_thumbnail(book)

    def _match_by_title(self, cache_entry, book, db, update_metadata,
                        get_covers, desired_thumbnail_height, first_call,
                        book_ids_to_refresh, book_formats_to_send,
                        books_with_future_dates):
        app_id = getattr(book, 'application_id', None)
        if app_id in cache_entry['db_ids']:
            self._update_book_metadata(app_id, book, db, get_covers, desired_thumbnail_height)
            book.in_library = 'APP_ID'
            return
        db_id = getattr(book, 'db_id', None)
        if db_id in cache_entry['db_ids']:
            self._update_book_metadata(db_id, book, db, get_covers, desired_thumbnail_height)
            book.in_library = 'DB_ID'
            book.application_id = db_id
            return
        book.application_id = None
        if book.authors:
            authors_key = self._clean_string(authors_to_string(book.authors))
            if authors_key in cache_entry['authors']:
                id_ = cache_entry['authors'][authors_key]
                self._update_book_metadata(id_, book, db, get_covers, desired_thumbnail_height)
                book.in_library = 'AUTHOR'
                book.application_id = id_
            elif authors_key in cache_entry['author_sort']:
                id_ = cache_entry['author_sort'][authors_key]
                self._update_book_metadata(id_, book, db, get_covers, desired_thumbnail_height)
                book.in_library = 'AUTH_SORT'
                book.application_id = id_

    def _sync_metadata(self, booklists, add_as_step_to_job):
        plugboards = self.library_view.model().db.prefs.get('plugboards', {})
        self.device_manager.sync_booklists(
            FunctionDispatcher(self.metadata_synced), booklists,
            plugboards, add_as_step_to_job)

    def _refresh_gui(self, book_ids):
        try:
            prints('DeviceJob: set_books_in_library refreshing GUI for ',
                   len(book_ids), 'books')
            self.library_view.model().refresh_ids(book_ids,
                                  current_row=self.library_view.currentIndex().row())
        except:
            traceback.print_exc()

    def _upload_missing_formats(self, book_formats_to_send, db):
        files, names, metadata = [], [], []
        for id_, fmt_name in book_formats_to_send:
            ext = os.path.splitext(fmt_name)[1][1:]
            fmt_info = db.new_api.format_metadata(id_, ext)
            if fmt_info:
                try:
                    pt = PersistentTemporaryFile(suffix='caltmpfmt.'+ext)
                    db.new_api.copy_format_to(id_, ext, pt)
                    pt.close()
                    files.append(filename_to_unicode(os.path.abspath(pt.name)))
                    names.append(fmt_name)
                    mi = db.new_api.get_metadata(id_, get_cover=True)
                    self.update_thumbnail(mi)
                    metadata.append(mi)
                except:
                    prints('Problem creating temporary file for', fmt_name)
                    traceback.print_exc()
        if files:
            self.upload_books(files, names, metadata)

    def _show_future_date_warning(self, books):
        try:
            d = error_dialog(self, _('Book format sync problem'),
                             _('Some book formats in your library cannot be '
                               'synced because they have dates in the future'),
                             det_msg='\n'.join(books),
                             show=False,
                             show_copy_button=True)
            d.show()
        except:
            traceback.print_exc()
    # }}}

