                                 text, parent, QListWidgetItem.UserType)
        if timestamp is not None:
            ts = timestamp.astimezone(local_tz)
            t = strftime('%a, %d %b %Y [%H:%M:%S]', ts.timetuple())
            tip = _('Last modified: %s\n\nDouble click to view') % t
            self.setToolTip(tip)
