    def __init__(self, parent, copy_fmt):
        super(FormatsManager, self).__init__(parent)
        self.dialog = parent
        self.copy_fmt = copy_fmt
        self.changed = False
        self.l = QGridLayout(self)
        self.cover_from_format_button = self._create_toolbutton('default_cover.png',
                _('Set the cover for the book from the selected format'))
        self.metadata_from_format_button = self._create_toolbutton('edit_input.png',
                _('Set metadata for the book from the selected format'))
        self.add_format_button = self._create_toolbutton('add_book.png',
                _('Add a format to this book'), self.add_format)
        self.remove_format_button = self._create_toolbutton('trash.png',
                _('Remove the selected format from this book'), self.remove_format)
        self.formats = FormatList(self)
        self.formats.setAcceptDrops(True)
        self.formats.formats_dropped.connect(self.formats_dropped)
        self.formats.restore_fmt.connect(self.restore_fmt)
        self.formats.delete_format.connect(self.remove_format)
        self.formats.itemDoubleClicked.connect(self.show_format)
        self.formats.setDragDropMode(self.formats.DropOnly)
        self.formats.setIconSize(QSize(32, 32))
        self.formats.setMaximumWidth(200)
        self.l.addWidget(self.cover_from_format_button, 0, 0, 1, 1)
        self.l.addWidget(self.metadata_from_format_button, 2, 0, 1, 1)
        self.l.addWidget(self.add_format_button, 0, 2, 1, 1)
        self.l.addWidget(self.remove_format_button, 2, 2, 1, 1)
        self.l.addWidget(self.formats, 0, 1, 3, 1)
        self.temp_files = []

    def _create_toolbutton(self, icon_name, tooltip, slot=None):
        btn = QToolButton(self)
        btn.setIcon(QIcon(I(icon_name)))
        btn.setIconSize(QSize(32, 32))
        btn.setToolTip(tooltip)
        if slot:
            btn.clicked.connect(slot)
        return btn

    def initialize(self, db, id_):
        self.changed = False
        self.formats.clear()
        exts = db.formats(id_, index_is_id=True)
        self.original_val = set()
        if exts:
            for ext in exts.split(','):
                if not ext:
                    continue
                size = db.sizeof_format(id_, ext, index_is_id=True)
                timestamp = db.format_last_modified(id_, ext)
                if size is None:
                    continue
                Format(self.formats, ext, size, timestamp=timestamp)
                self.original_val.add(ext.lower())

    def apply_to_metadata(self, mi):
        pass

    def commit(self, db, id_):
        if not self.changed:
            return
        old_exts, new_exts, paths = set(), set(), {}
        for row in range(self.formats.count()):
            fmt = self.formats.item(row)
            ext = fmt.ext.lower()
            path = fmt.path
            if 'unknown' in ext:
                ext = None
            if path:
                new_exts.add(ext)
                paths[ext] = path
            else:
                old_exts.add(ext)
        for ext in new_exts:
            with SpooledTemporaryFile(SPOOL_SIZE) as spool:
                with open(paths[ext], 'rb') as f:
                    shutil.copyfileobj(f, spool)
                spool.seek(0)
                db.add_format(id_, ext, spool, notify=False, index_is_id=True)
        dbfmts = db.formats(id_, index_is_id=True)
        db_exts = set([fl.lower() for fl in (dbfmts.split(',') if dbfmts else [])])
        all_exts = new_exts.union(old_exts)
        for ext in db_exts:
            if ext not in all_exts and ext in self.original_val:
                db.remove_format(id_, ext, notify=False, index_is_id=True)
        self.changed = False

    def add_format(self):
        files = choose_files(self, 'add formats dialog',
                             _("Choose formats for ") + self.dialog.title.current_val,
                             [(_('Books'), BOOK_EXTENSIONS)])
        self._add_formats(files)

    def restore_fmt(self, fmt):
        pt = PersistentTemporaryFile(suffix='_restore_fmt.' + fmt.lower())
        ofmt = 'ORIGINAL_' + fmt
        with pt:
            self.copy_fmt(ofmt, pt)
        self._add_formats((pt.name,))
        self.temp_files.append(pt.name)
        self.changed = True
        self.formats.remove_format(ofmt)

    def _add_formats(self, paths):
        added = False
        if not paths:
            return added
        bad_perms = []
        for path in paths:
            path = os.path.abspath(path)
            if not os.access(path, os.R_OK):
                bad_perms.append(path)
                continue
            path = run_plugins_on_import(path) or path
            stat = os.stat(path)
            size = stat.st_size
            ext = os.path.splitext(path)[1].lower().replace('.', '')
            timestamp = utcfromtimestamp(stat.st_mtime)
            self._replace_existing_format(ext)
            Format(self.formats, ext, size, path=path, timestamp=timestamp)
            self.changed = True
            added = True
        if bad_perms:
            error_dialog(self, _('No permission'),
                         _('You do not have permission to read the following files:'),
                         det_msg='\n'.join(bad_perms), show=True)
        return added

    def _replace_existing_format(self, ext):
        for i in range(self.formats.count()):
            fmt = self.formats.item(i)
            if fmt.ext.lower() == ext:
                self.formats.takeItem(i)
                break

    def formats_dropped(self, event, paths):
        if self._add_formats(paths):
            event.accept()

    def remove_format(self):
        rows = self.formats.selectionModel().selectedRows(0)
        for row in rows:
            self.formats.takeItem(row.row())
            self.changed = True

    def show_format(self, item):
        self.dialog.do_view_format(item.path, item.ext)

    def get_selected_format(self):
        row = self.formats.currentRow()
        fmt = self.formats.item(row)
        if fmt is None and self.formats.count() == 1:
            fmt = self.formats.item(0)
        if fmt is None:
            error_dialog(self, _('No format selected'), _('No format selected')).exec_()
            return None
        return fmt.ext.lower()

    def get_format_path(self, db, id_, fmt):
        for i in range(self.formats.count()):
            f = self.formats.item(i)
            if f.ext.lower() == fmt:
                return f.path if f.path else db.format(id_, fmt, as_path=True, index_is_id=True)

    def get_selected_format_metadata(self, db, id_):
        old = prefs['read_file_metadata']
        prefs['read_file_metadata'] = True
        try:
            fmt = self.formats.item(self.formats.currentRow())
            if fmt is None and self.formats.count() == 1:
                fmt = self.formats.item(0)
            if fmt is None:
                error_dialog(self, _('No format selected'), _('No format selected')).exec_()
                return None, None
            ext = fmt.ext.lower()
            stream = db.format(id_, ext, as_file=True, index_is_id=True) if fmt.path is None else open(fmt.path, 'rb')
            with stream:
                mi = get_metadata(stream, ext)
            return mi, ext
        except Exception:
            import traceback
            error_dialog(self, _('Could not read metadata'),
                         _('Could not read metadata from %s format') % ext.upper(),
                         det_msg=traceback.format_exc(), show=True)
            return None, None
        finally:
            if old != prefs['read_file_metadata']:
                prefs['read_file_metadata'] = old

    def break_cycles(self):
        self.dialog = None
        self.copy_fmt = None
        for name in self.temp_files:
            try:
                os.remove(name)
            except Exception:
                pass
        self.temp_files = []


class Cover(ImageView):
    download_cover = pyqtSignal()

    def __init__(self, parent):
        super(Cover, self).__init__(parent, show_size_pref_name='edit_metadata_cover_widget', default_show_size=True)
        self.dialog = parent
        self._cdata = None
        self.cdata_before_trim = None
        self.cover_changed.connect(self.set_pixmap_from_data)

        class CB(RightClickButton):
            def __init__(self, text, icon=None, action=None):
                super(CB, self).__init__(parent)
                self.setText(text)
                if icon:
                    self.setIcon(QIcon(I(icon)))
                self.setSizePolicy(QSizePolicy.MinimumExpanding, QSizePolicy.Preferred)
                self.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
                if action:
                    self.clicked.connect(action)

        self.select_cover_button = CB(_('&Browse'), 'document_open.png', self.select_cover)
        self.trim_cover_button = CB(_('T&rim borders'), 'trim.png')
        self.trim_cover_button.setToolTip(_(
            'Automatically detect and remove extra space at the cover\'s edges.\n'
            'Pressing it repeatedly can sometimes remove stubborn borders.'))
        trim_menu = QMenu()
        self.trim_cover_button.setPopupMode(QToolButton.InstantPopup)
        self.trim_cover_button.setMenu(trim_menu)
        trim_menu.addAction(QIcon(I('trim.png')), _('Automatically trim borders'), self.trim_cover)
        trim_menu.addSeparator()
        trim_menu.addAction(_('Trim borders manually'), self.manual_trim_cover)
        trim_menu.addAction(QIcon(I('edit-undo.png')), _('Undo last trim'), self.undo_trim)
        self.remove_cover_button = CB(_('&Remove'), 'trash.png', self.remove_cover)
        self.download_cover_button = CB(_('Download co&ver'), 'arrow-down.png', self.download_cover)
        self.generate_cover_button = CB(_('&Generate cover'), 'default_cover.png', self.generate_cover)
        gen_menu = QMenu()
        self.generate_cover_button.setMenu(gen_menu)
        gen_menu.addAction(QIcon(I('config.png')), _('Customize the styles and colors of the generated cover'), self.custom_cover)
        self.generate_cover_button.setPopupMode(QToolButton.DelayedPopup)
        self.buttons = [self.select_cover_button, self.remove_cover_button,
                        self.trim_cover_button, self.download_cover_button,
                        self.generate_cover_button]
        self.frame_size = (300, 400)
        self.setSizePolicy(QSizePolicy(QSizePolicy.Preferred, QSizePolicy.Preferred))

    def undo_trim(self):
        if self.cdata_before_trim:
            self.current_val = self.cdata_before_trim
            self.cdata_before_trim = None

    def frame_resized(self, ev):
        sz = ev.size()
        self.frame_size = (sz.width() // 3, sz.height())

    def sizeHint(self):
        return QSize(*self.frame_size)

    def select_cover(self):
        files = choose_images(self, 'change cover dialog',
                              _('Choose cover for ') + self.dialog.title.current_val)
        if not files:
            return
        path = files[0]
        if not os.access(path, os.R_OK):
            error_dialog(self, _('Cannot read'),
                         _('You do not have permission to read the file: ') + path).exec_()
            return
        try:
            with open(path, "rb") as f:
                cover = f.read()
        except IOError as e:
            error_dialog(self, _('Error reading file'),
                         _("<p>There was an error reading from file: <br /><b>") + path + "</b></p><br />" + str(e)).exec_()
            return
        if cover:
            orig = self.current_val
            self.current_val = cover
            if self.current_val is None:
                self.current_val = orig
                error_dialog(self, _("Not a valid picture"),
                             path + _(" is not a valid picture"), show=True)

    def remove_cover(self):
        self.current_val = None

    def trim_cover(self):
        cdata = self.current_val
        if not cdata:
            return
        from calibre.utils.img import remove_borders_from_image, image_to_data, image_from_data
        img = image_from_data(cdata)
        nimg = remove_borders_from_image(img)
        if nimg is not img:
            self.cdata_before_trim = cdata
            self.current_val = image_to_data(nimg, fmt='png')

    def manual_trim_cover(self):
        cdata = self.current_val
        from calibre.gui2.dialogs.trim_image import TrimImage
        d = TrimImage(cdata, parent=self)
        if d.exec_() == d.Accepted and d.image_data is not None:
            self.current_val = d.image_data
            self.cdata_before_trim = cdata

    def generate_cover(self):
        from calibre.ebooks.covers import generate_cover
        mi = self.dialog.to_book_metadata()
        self.current_val = generate_cover(mi)

    def custom_cover(self):
        from calibre.ebooks.covers import generate_cover
        from calibre.gui2.covers import CoverSettingsDialog
        mi = self.dialog.to_book_metadata()
        d = CoverSettingsDialog(mi=mi, parent=self)
        if d.exec_() == d.Accepted:
            self.current_val = generate_cover(mi, prefs=d.prefs_for_rendering)

    def set_pixmap_from_data(self, data):
        if not data:
            self.current_val = None
            return
        orig = self.current_val
        self.current_val = data
        if self.current_val is None:
            error_dialog(self, _('Invalid cover'),
                         _('Could not change cover as the image is invalid.'), show=True)
            self.current_val = orig

    def initialize(self, db, id_):
        self._cdata = None
        self.cdata_before_trim = None
        self.current_val = db.cover(id_, index_is_id=True)
        self.original_val = self.current_val

    @property
    def changed(self):
        return self.current_val != self.original_val

    @dynamic_property
    def current_val(self):
        def fget(self):
            return self._cdata

        def fset(self, cdata):
            self._cdata = None
            self.cdata_before_trim = None
            pm = QPixmap()
            if cdata:
                pm.loadFromData(cdata)
            if pm.isNull():
                pm = QPixmap(I('default_cover.png'))
            else:
                self._cdata = cdata
            pm.setDevicePixelRatio(getattr(self, 'devicePixelRatioF', self.devicePixelRatio)())
            self.setPixmap(pm)
            tip = _('This book has no cover') if not self._cdata else _('Cover size: %(width)d x %(height)d pixels') % dict(width=pm.width(), height=pm.height())
            self.setToolTip(tip)

        return property(fget=fget, fset=fset)

    def commit(self, db, id_):
        if self.changed:
            if self.current_val:
                db.set_cover(id_, self.current_val, notify=False, commit=False)
            else:
                db.remove_cover(id_, notify=False, commit=False)

    def break_cycles(self):
        try:
            self.cover_changed.disconnect()
        except Exception:
            pass
        self.dialog = self._cdata = self.current_val = self.original_val = None

    def apply_to_metadata(self, mi):
        from calibre.utils.imghdr import what
        cdata = self.current_val
        if cdata:
            mi.cover_data = (what(None, cdata), cdata)


